"""ODC IaC Generator — ODC Workflow Step 3.

Generates Terraform, Ansible, and validation artifacts for observability infrastructure.
Outputs JSON with artifact paths to stdout.
"""
import argparse
import json
import sys
import uuid
from datetime import datetime, timezone
from pathlib import Path

_ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(_ROOT))

_ARTIFACTS_DIR = _ROOT / "data" / "studio_artifacts" / "odc"

# ── Terraform resource blocks ────────────────────────────────────────────────

_TF_HEADER = '''\
# Observability Infrastructure — Generated by ICDEV™ ODC Workflow
# Canvas: odc
# Generated: {ts}
# DO NOT EDIT — regenerate via ODC Workflow

terraform {{
  required_providers {{
    aws = {{
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }}
  }}
  required_version = ">= 1.6.0"
}}

provider "aws" {{
  region = var.aws_region
}}

locals {{
  common_tags = {{
    ManagedBy   = "icdev-odc"
    Environment = var.environment
    Canvas      = "odc"
  }}
}}

# ── KMS Key for Log Encryption ────────────────────────────────────────────────

resource "aws_kms_key" "odc_logs" {{
  description             = "ICDEV ODC log encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({{
    Version = "2012-10-17"
    Statement = [
      {{
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Principal = {{
          Service = "logs.${{data.aws_region.current.name}}.amazonaws.com"
        }}
        Action   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
        Resource = "*"
      }},
      {{
        Sid       = "AllowKeyAdministration"
        Effect    = "Allow"
        Principal = {{ AWS = "arn:aws:iam::${{data.aws_caller_identity.current.account_id}}:root" }}
        Action    = "kms:*"
        Resource  = "*"
      }},
    ]
  }})
  tags = local.common_tags
}}

resource "aws_kms_alias" "odc_logs_alias" {{
  name          = "alias/icdev-odc-logs"
  target_key_id = aws_kms_key.odc_logs.key_id
}}

# ── CloudWatch Log Groups ─────────────────────────────────────────────────────

resource "aws_cloudwatch_log_group" "app_logs" {{
  name              = "/icdev/${{var.environment}}/app"
  retention_in_days = var.retention_days
  kms_key_id        = aws_kms_key.odc_logs.arn
  tags              = local.common_tags
}}

resource "aws_cloudwatch_log_group" "security_logs" {{
  name              = "/icdev/${{var.environment}}/security"
  retention_in_days = var.retention_days
  kms_key_id        = aws_kms_key.odc_logs.arn
  tags              = local.common_tags
}}

# ── SNS Topic — Alert Notifications ─────────────────────────────────────────

resource "aws_sns_topic" "alerts" {{
  name = "icdev-odc-alerts-${{var.environment}}"
  tags = local.common_tags
}}

resource "aws_sns_topic_subscription" "alerts_email" {{
  topic_arn = aws_sns_topic.alerts.arn
  protocol  = "email"
  endpoint  = var.alert_email
}}

# ── CloudWatch Metric Alarms ──────────────────────────────────────────────────

resource "aws_cloudwatch_metric_alarm" "high_cpu" {{
  alarm_name          = "icdev-${{var.environment}}-high-cpu"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 2
  metric_name         = "CPUUtilization"
  namespace           = "AWS/ECS"
  period              = 300
  statistic           = "Average"
  threshold           = 80
  alarm_description   = "CPU utilization above 80% for 10 minutes"
  alarm_actions       = [aws_sns_topic.alerts.arn]
  ok_actions          = [aws_sns_topic.alerts.arn]
  tags                = local.common_tags
}}

resource "aws_cloudwatch_metric_alarm" "high_error_rate" {{
  alarm_name          = "icdev-${{var.environment}}-high-error-rate"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 2
  metric_name         = "HTTPCode_Target_5XX_Count"
  namespace           = "AWS/ApplicationELB"
  period              = 300
  statistic           = "Sum"
  threshold           = 10
  alarm_description   = "5xx error count above 10 in 10 minutes"
  alarm_actions       = [aws_sns_topic.alerts.arn]
  treat_missing_data  = "notBreaching"
  tags                = local.common_tags
}}

# ── CloudWatch Dashboard ──────────────────────────────────────────────────────

resource "aws_cloudwatch_dashboard" "ops" {{
  dashboard_name = "icdev-${{var.environment}}-ops"
  dashboard_body = jsonencode({{
    widgets = [
      {{
        type       = "metric"
        x          = 0
        y          = 0
        width      = 12
        height     = 6
        properties = {{
          title   = "CPU Utilization"
          metrics = [["AWS/ECS", "CPUUtilization", {{stat = "Average"}}]]
          period  = 300
          view    = "timeSeries"
        }}
      }},
      {{
        type       = "metric"
        x          = 12
        y          = 0
        width      = 12
        height     = 6
        properties = {{
          title   = "HTTP 5xx Errors"
          metrics = [["AWS/ApplicationELB", "HTTPCode_Target_5XX_Count", {{stat = "Sum"}}]]
          period  = 300
          view    = "timeSeries"
        }}
      }},
      {{
        type       = "log"
        x          = 0
        y          = 6
        width      = 24
        height     = 6
        properties = {{
          title   = "Application Log Errors (last 1h)"
          query   = "SOURCE '/icdev/${{var.environment}}/app' | fields @timestamp, @message | filter @message like /ERROR/ | sort @timestamp desc | limit 100"
          view    = "table"
          region  = var.aws_region
        }}
      }},
    ]
  }})
}}

# ── Amazon Managed Prometheus ─────────────────────────────────────────────────

resource "aws_prometheus_workspace" "odc" {{
  alias = "icdev-${{var.environment}}-prometheus"
  tags  = local.common_tags
}}

# ── SSM Parameter Store ───────────────────────────────────────────────────────

resource "aws_ssm_parameter" "odc_config" {{
  name  = "/icdev/odc/config"
  type  = "SecureString"
  value = jsonencode({{
    environment       = var.environment
    app_log_group     = aws_cloudwatch_log_group.app_logs.name
    security_log_group = aws_cloudwatch_log_group.security_logs.name
    sns_topic_arn     = aws_sns_topic.alerts.arn
    prometheus_endpoint = aws_prometheus_workspace.odc.prometheus_endpoint
    retention_days    = var.retention_days
  }})
  key_id = aws_kms_key.odc_logs.key_id
  tags   = local.common_tags
}}

# ── Data Sources ──────────────────────────────────────────────────────────────

data "aws_caller_identity" "current" {{}}
data "aws_region" "current" {{}}
'''

